import {subjects,questions} from './curriculum.js';
import {extraQuestions} from './exam-bank.js';
const bank=[...questions,...extraQuestions];
export function quickPool(subject='all'){
 return [...new Map(bank.filter(q=>subject==='all'||q.subject===subject).map(q=>[q.id,q])).values()];
}
export function quickConfig(subject,count){
 if(![10,20].includes(count))throw new Error('請選擇 10 或 20 題');
 const name=subject==='all'?'全科混合':subjects.find(s=>s.id===subject)?.name;
 if(!name)throw new Error('找不到科目');
 return {title:`趣味闖關・${name}・${Math.min(count,quickPool(subject).length)} 題`,mode:'practice',count};
}
export function renderQuickQuiz(container,start){
 const activeRecallSvg = `<div class="diagram-box" style="margin:18px 0;"><div class="diagram-header"><span class="diagram-icon">⚡</span><div class="diagram-title-group"><strong>測試效應（Testing Effect）與主動提取閉環架構圖</strong><span class="subtle">隨機抽題檢索 ➔ 提示鷹架引導 ➔ 解析校正心智模型 ➔ 錯題自動歸檔回練</span></div></div><div class="diagram-svg-wrap"><svg viewBox="0 0 640 115" style="width:100%;max-width:640px;display:block;margin:0 auto;" role="img" aria-label="主動提取與錯題閉環學習圖"><rect x="6" y="6" width="628" height="103" rx="10" fill="#fbfcfb" stroke="#d6dfd9" stroke-width="1.2"/><g transform="translate(16, 15)"><rect width="138" height="85" rx="8" fill="#e8f3ee" stroke="#2f5e4e" stroke-width="1.5"/><text x="69" y="24" font-size="10.5" font-weight="800" fill="#1e3c30" text-anchor="middle">① 隨機抽題檢索</text><text x="69" y="46" font-size="8.5" font-weight="700" fill="#223832" text-anchor="middle">440 題跨科題庫</text><text x="69" y="66" font-size="8" fill="#5a6d64" text-anchor="middle">打亂題序與選項防死背</text></g><path d="M 157 57 L 173 57" stroke="#2f5e4e" stroke-width="2"/><polygon points="175,57 169,53 169,61" fill="#2f5e4e"/><g transform="translate(177, 15)"><rect width="138" height="85" rx="8" fill="#e6f0f9" stroke="#2b5b84" stroke-width="1.5"/><text x="69" y="24" font-size="10.5" font-weight="800" fill="#2b5b84" text-anchor="middle">② 獨立思考或提示</text><text x="69" y="46" font-size="8.5" font-weight="700" fill="#223832" text-anchor="middle">無提示答對獲理解之星</text><text x="69" y="66" font-size="8" fill="#5a6d64" text-anchor="middle">卡關時點開審題線索</text></g><path d="M 318 57 L 334 57" stroke="#2b5b84" stroke-width="2"/><polygon points="336,57 330,53 330,61" fill="#2b5b84"/><g transform="translate(338, 15)"><rect width="138" height="85" rx="8" fill="#fdf6e2" stroke="#b07d2b" stroke-width="1.5"/><text x="69" y="24" font-size="10.5" font-weight="800" fill="#b07d2b" text-anchor="middle">③ 即時解析對照</text><text x="69" y="46" font-size="8.5" font-weight="700" fill="#223832" text-anchor="middle">核對定義與適用邊界</text><text x="69" y="66" font-size="8" fill="#5a6d64" text-anchor="middle">直連 188 課綱教學單元</text></g><path d="M 479 57 L 495 57" stroke="#b07d2b" stroke-width="2"/><polygon points="497,57 491,53 491,61" fill="#b07d2b"/><g transform="translate(499, 15)"><rect width="125" height="85" rx="8" fill="#faece8" stroke="#b84735" stroke-width="1.5"/><text x="62" y="24" font-size="10.5" font-weight="800" fill="#b84735" text-anchor="middle">④ 錯題自動歸檔</text><text x="62" y="46" font-size="8.5" font-weight="700" fill="#223832" text-anchor="middle">匯入錯題與複習頁</text><text x="62" y="66" font-size="8" fill="#5a6d64" text-anchor="middle">螺旋回練直至完全精熟</text></g></svg></div></div>`;
 container.innerHTML=`<div class="eyebrow">QUICK QUIZ · PLAY & LEARN</div><h1>抽一組題，來闖關！</h1><p class="muted">選一科，隨機抽題。用提示找方向，用解析把觀念學起來。</p><section class="panel quick-panel"><span class="tag accent">不限時 · 即時解析 · 自動儲存</span><h2>① 今天想挑戰哪一科？</h2><div class="quick-subjects" role="group" aria-label="選擇測驗科目">${[{id:'all',name:'全科驚喜包'},...subjects].map(s=>`<button type="button" class="chip" data-quick-subject="${s.id}" aria-pressed="${s.id==='all'}">${s.name}<small>${quickPool(s.id).length} 題</small></button>`).join('')}</div><h2>② 選擇你的回合</h2><div class="quick-rounds" role="group" aria-label="選擇題數"><button type="button" class="quick-round" data-quick-count="10" aria-pressed="true"><strong>10 題暖身</strong><span>小小一步，啟動腦力</span></button><button type="button" class="quick-round" data-quick-count="20" aria-pressed="false"><strong>20 題挑戰</strong><span>多想一點，探索更多</span></button></div><p id="quick-summary" class="notice" role="status"></p><button type="button" id="quick-start" class="button">隨機抽題，開始闖關 →</button><a href="#/quiz" class="button ghost">繼續尚未完成的測驗</a><p class="subtle">範圍為七至九年級原創選擇題，不受上方年級篩選限制，不含聽力與學測轉錄題。每回合不重複抽題；不同回合可能再次遇到同一道題。</p></section><section class="panel"><h2>你的闖關小任務</h2><div class="quick-missions"><p>① 先自己想答案<br><small>每次獨立答對，收下一顆理解之星。</small></p><p>② 卡住就看提示<br><small>看懂解析比猜中更有收穫。</small></p><p>③ 交卷後回顧<br><small>錯題會加入複習，再挑戰一次！</small></p></div>${activeRecallSvg}<div class="table-wrap" style="margin-top:20px;"><table class="teaching-table"><caption>趣味闖關認知之星與精通等級規準表</caption><thead><tr><th scope="col" style="width:18%;">星級榮譽</th><th scope="col" style="width:26%;">獨立答對率門檻</th><th scope="col" style="width:28%;">認知大腦狀態</th><th scope="col" style="width:28%;">進階通關建議</th></tr></thead><tbody><tr><th scope="row" style="color:#c4821a;">★★★ 三星宗師</th><td>獨立答對 90% 以上 (無提示)</td><td>心智模型完整，能迅速穿透題眼，直達正確定理。</td><td>挑戰計時會考全真模考或進入高難度混合題組！</td></tr><tr><th scope="row" style="color:#2d5c48;">★★ 二星高手</th><td>獨立答對 70% ~ 89%</td><td>核心概念掌握良好，僅少數情境細節或計算需防呆。</td><td>針對看過提示的題目，隔天在錯題本回練一次。</td></tr><tr><th scope="row" style="color:#3b789e;">★ 一星潛力</th><td>獨立答對 50% ~ 69%</td><td>部分單元存在認知盲點或審題跳步，仍待打底。</td><td>點擊「回到觀念講解」，研讀 Stage 02/03 思維鏈。</td></tr></tbody></table></div></section>`;
 let subject='all',count=10;
 const update=()=>{
  container.querySelectorAll('[data-quick-subject]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quickSubject===subject)));
  container.querySelectorAll('[data-quick-count]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.quickCount)===count)));
  const available=quickPool(subject).length,name=subject==='all'?'全科混合':subjects.find(s=>s.id===subject).name;
  container.querySelector('#quick-summary').textContent=`${name}：從 ${available} 題隨機抽出 ${Math.min(count,available)} 題，題目與選項順序都會打亂。`+(available<count?` 本科目前不足 ${count} 題，將使用全部 ${available} 題，不重複湊題。`:'');
  container.querySelector('#quick-start').disabled=!available;
 };
 container.querySelectorAll('[data-quick-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.quickSubject;update();});
 container.querySelectorAll('[data-quick-count]').forEach(b=>b.onclick=()=>{count=Number(b.dataset.quickCount);update();});
 container.querySelector('#quick-start').onclick=()=>start(quickPool(subject),quickConfig(subject,count));
 update();
}
